import { expect, test } from 'vitest';
import { loadVariants } from './catalog';
test('missing advertisement has an explicit error', () => {
  expect(() => loadVariants(undefined)).toThrow('variant catalog unavailable');
});
test('preserves advertised variants', () => {
  expect(loadVariants(['low', 'high'])).toEqual(['low', 'high']);
});
